package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Original source and metadata of the exact Salesforce-admitted contract.
func TestRunBase64SourceContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeBase64Observe53.cls"), "@IsTest private class GladeBase64Observe53 {\n private static void probe(List<Object> rows,String label,String input) {\n  Map<String,Object> row=new Map<String,Object>{'n'=>label,'in'=>input}; String phase='decode';\n  try {Blob value=EncodingUtil.base64Decode(input);if(value==null){row.put('null',true);}else{phase='hex';row.put('bytes',value.size());row.put('hex',EncodingUtil.convertToHex(value).toLowerCase());}}\n  catch(Exception error){String message=error.getMessage();row.put('phase',phase);row.put('type',error.getTypeName());row.put('message',message);if(message!=null&&message.length()>160){row.put('message',message.left(160));row.put('fullMessageLength',message.length());row.put('fullMessageSha256',EncodingUtil.convertToHex(Crypto.generateDigest('SHA-256',Blob.valueOf(message))));}}\n  rows.add(row);\n }\n @IsTest static void observeOriginalDerivedKeys(){List<Object> rows=new List<Object>();\n  probe(rows,'string-first','TVRJek5BPT0');\n  probe(rows,'object-key','TVRJek5BPT0');\n  probe(rows,'source-second-pending','VFZFOVBRPT0');\n  probe(rows,'derived-first-padded','TVRJek5BPT0=');\n  probe(rows,'original-key-raw','MTIzNA==');\n  probe(rows,'second-key-raw','TVE9PQ==');\n  System.assertEquals(6,rows.size(),'All original probes complete');\n  System.assertEquals(new List<Object>{new Map<String,Object>{'hex'=>'4d54497a4e413d3d','bytes'=>8,'in'=>'TVRJek5BPT0','n'=>'string-first'},new Map<String,Object>{'hex'=>'4d54497a4e413d3d','bytes'=>8,'in'=>'TVRJek5BPT0','n'=>'object-key'},new Map<String,Object>{'hex'=>'5456453950513d3d','bytes'=>8,'in'=>'VFZFOVBRPT0','n'=>'source-second-pending'},new Map<String,Object>{'hex'=>'4d54497a4e413d3d','bytes'=>8,'in'=>'TVRJek5BPT0=','n'=>'derived-first-padded'},new Map<String,Object>{'hex'=>'31323334','bytes'=>4,'in'=>'MTIzNA==','n'=>'original-key-raw'},new Map<String,Object>{'hex'=>'4d513d3d','bytes'=>4,'in'=>'TVE9PQ==','n'=>'second-key-raw'}},rows,'Exact Salesforce decode values, errors, and continuation');\n }\n @IsTest static void observePadding(){List<Object> rows=new List<Object>();\n  probe(rows,'f-padded','Zg==');\n  probe(rows,'f-unpadded','Zg');\n  probe(rows,'fo-padded','Zm8=');\n  probe(rows,'fo-unpadded','Zm8');\n  probe(rows,'foo-no-padding','Zm9v');\n  probe(rows,'one-symbol','Z');\n  probe(rows,'under-padding','Zg=');\n  probe(rows,'extra-padding','Zg===');\n  System.assertEquals(8,rows.size(),'All original probes complete');\n  System.assertEquals(new List<Object>{new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>'Zg==','n'=>'f-padded'},new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>'Zg','n'=>'f-unpadded'},new Map<String,Object>{'hex'=>'666f','bytes'=>2,'in'=>'Zm8=','n'=>'fo-padded'},new Map<String,Object>{'hex'=>'666f','bytes'=>2,'in'=>'Zm8','n'=>'fo-unpadded'},new Map<String,Object>{'hex'=>'666f6f','bytes'=>3,'in'=>'Zm9v','n'=>'foo-no-padding'},new Map<String,Object>{'hex'=>'','bytes'=>0,'in'=>'Z','n'=>'one-symbol'},new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>'Zg=','n'=>'under-padding'},new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>'Zg===','n'=>'extra-padding'}},rows,'Exact Salesforce decode values, errors, and continuation');\n }\n @IsTest static void observeAlphabetAndWhitespace(){List<Object> rows=new List<Object>();\n  probe(rows,'standard-binary','+/8=');\n  probe(rows,'url-binary','-_8=');\n  probe(rows,'standard-unpadded','+/8');\n  probe(rows,'url-unpadded','-_8');\n  probe(rows,'embedded-space','Zm 9v');\n  probe(rows,'linebreak','Zm9v\\r\\n');\n  probe(rows,'invalid-scalar-fixture','not base64');\n  probe(rows,'punctuation','!');\n  System.assertEquals(8,rows.size(),'All original probes complete');\n  System.assertEquals(new List<Object>{new Map<String,Object>{'hex'=>'fbff','bytes'=>2,'in'=>'+/8=','n'=>'standard-binary'},new Map<String,Object>{'message'=>'Unrecognized base64 character: -','type'=>'System.StringException','phase'=>'decode','in'=>'-_8=','n'=>'url-binary'},new Map<String,Object>{'hex'=>'fbff','bytes'=>2,'in'=>'+/8','n'=>'standard-unpadded'},new Map<String,Object>{'message'=>'Unrecognized base64 character: -','type'=>'System.StringException','phase'=>'decode','in'=>'-_8','n'=>'url-unpadded'},new Map<String,Object>{'hex'=>'666f6f','bytes'=>3,'in'=>'Zm 9v','n'=>'embedded-space'},new Map<String,Object>{'hex'=>'666f6f','bytes'=>3,'in'=>'Zm9v\\r\\n','n'=>'linebreak'},new Map<String,Object>{'hex'=>'9e8b5b6ac7ba','bytes'=>6,'in'=>'not base64','n'=>'invalid-scalar-fixture'},new Map<String,Object>{'message'=>'Unrecognized base64 character: !','type'=>'System.StringException','phase'=>'decode','in'=>'!','n'=>'punctuation'}},rows,'Exact Salesforce decode values, errors, and continuation');\n }\n @IsTest static void observeNullEmptyAndTrailing(){List<Object> rows=new List<Object>();\n  probe(rows,'null',null);\n  probe(rows,'empty','');\n  probe(rows,'leading-padding','=Zg==');\n  probe(rows,'trailing-data','Zg==AA');\n  probe(rows,'trailing-space','Zg== ');\n  probe(rows,'leading-space',' Zg==');\n  System.assertEquals(6,rows.size(),'All original probes complete');\n  System.assertEquals(new List<Object>{new Map<String,Object>{'message'=>'Argument cannot be null.','type'=>'System.NullPointerException','phase'=>'decode','in'=>null,'n'=>'null'},new Map<String,Object>{'hex'=>'','bytes'=>0,'in'=>'','n'=>'empty'},new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>'=Zg==','n'=>'leading-padding'},new Map<String,Object>{'hex'=>'660000','bytes'=>3,'in'=>'Zg==AA','n'=>'trailing-data'},new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>'Zg== ','n'=>'trailing-space'},new Map<String,Object>{'hex'=>'66','bytes'=>1,'in'=>' Zg==','n'=>'leading-space'}},rows,'Exact Salesforce decode values, errors, and continuation');\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeBase64Observe53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Failed != 0 || got.Skipped != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact source contracts failed: %s", data)
	}
}
